    {
        "name": "Adrenal Alopecia",
        "name_ja": "副腎性脱毛",
        "symptoms": {"hair_loss", "thinning_skin", "itching", "vulvar_swelling"},
        "description": "線維性結合組織の悪性腫瘍で、局所浸潤性を示すことがあります。",
        "description_ja": "副腎ホルモン過剰による左右対称の脱毛で、副腎疾患の代表的症状です。",
        "urgency": "moderate",
        "recommended_tests": ["adrenal_panel", "ultrasound"],
        "causes": "Excess adrenal sex hormone production (estradiol, 17-hydroxyprogesterone, DHEA-S) causing bilateral symmetric alopecia. A hallmark clinical sign of adrenal disease in ferrets.",
        "causes_ja": "Ferretにおける副腎性脱毛の原因: 副腎ホルモン過剰による左右対称の脱毛で、副腎疾患の代表的症状です。",
        "pathophysiology": "副腎性脱毛はFerretにおける代謝・内分泌疾患である。基礎病態はホルモンのフィードバックループ、酵素活性、または基質代謝の調節障害を伴う。循環ホルモン、電解質、代謝中間体のバランス異常が複数の臓器系にわたる細胞機能に影響を及ぼす。代償機構が一時的に恒常性を維持するが、最終的に代償不全に陥り、進行性の臨床的悪化と多臓器への影響を引き起こす。",
        "pathophysiology_ja": "副腎性脱毛はFerretにおける代謝・内分泌疾患である。基礎病態はホルモンのフィードバックループ、酵素活性、または基質代謝の調節障害を伴う。循環ホルモン、電解質、代謝中間体のバランス異常が複数の臓器系にわたる細胞機能に影響を及ぼす。代償機構が一時的に恒常性を維持するが、最終的に代償不全に陥り、進行性の臨床的悪化と多臓器への影響を引き起こす。",
        "treatment": "",
        "treatment_ja": "フェレットにおける副腎性脱毛の治療は基礎となるホルモン・代謝異常を標的とする。ホルモン補充療法または抑制療法により生理的バランスを回復する。食事療法で代謝疾患の栄養面に対処する。ホルモンレベル、血糖、電解質、臓器機能マーカーの定期的モニタリングにより用量調整を行う。二次的合併症（臓器障害、感染）の併行管理が不可欠である。長期または生涯にわたる治療が必要な場合がある。",
        "prevention": "線維肉腫の予防は限定的であるが、ホルモン依存性腫瘍軽減のための避妊・去勢手術、既知の発癌物質の回避、早期発見のための定期健診、適正体型の維持、該当する場合は遺伝的素因軽減のための責任ある繁殖が含まれる。",
        "prevention_ja": "副腎性脱毛の予防には適切な食事設計、血液検査を含む定期的な健康モニタリング、健康体重の維持、過剰なおやつや不適切な食事の回避、無症候性変化の早期発見時の迅速な介入が含まれる。",
        "prognosis": "",
        "prognosis_ja": "副腎性脱毛の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
